const SHORT = { NAE: 'NA East', NAW: 'NA West', EU: 'Europe', LA: 'Latin America', AS: 'Asia' }
const MATCHED_SINCE = '4 Oct 2026'
// Every world in worlds.json has prices today. Two EU worlds are flipped here only to show the "no prices yet" state.
const FAKE_NO_DATA = new Set([11323, 12323])

const REGIONS = RAW_WORLDS.map((r) => {
  const worlds = []
  for (const p of r.pairs) {
    const e = { ...p.elyos, side: 'Elyos', region: r.code, matchedSince: MATCHED_SINCE }
    const a = { ...p.asmodian, side: 'Asmodian', region: r.code, matchedSince: MATCHED_SINCE }
    e.matchedWith = a; a.matchedWith = e
    for (const x of [e, a]) if (FAKE_NO_DATA.has(x.id)) x.hasData = false
    worlds.push(e, a)
  }
  return { code: r.code, name: r.name, worlds }
})
const WORLDS = REGIONS.flatMap((r) => r.worlds)
const ITEM = Object.fromEntries(ITEMS.map((i) => [i.name, i]))

const PROFS = [
  { key: 'Blacksmithing', short: 'B', game: 'Blacksmithing' },
  { key: 'Tailoring', short: 'T', game: 'Armorsmithing' },
  { key: 'Jewelcrafting', short: 'J', game: 'Handicrafting' },
  { key: 'Alchemy', short: 'A', game: 'Alchemy' },
  { key: 'Cooking', short: 'C', game: 'Cooking' },
]
const state = {
  worldId: 11304,
  mastery: { Blacksmithing: 100, Tailoring: 100, Jewelcrafting: 100, Alchemy: 100, Cooking: 100 },
  tax: 5,
  view: 'calc',
}
const picker = { region: 'EU', side: 'Elyos', step: 'region', q: '' }
const $ = (s, el = document) => el.querySelector(s)
const esc = (s) => String(s).replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' })[c])
const world = () => WORLDS.find((w) => w.id === state.worldId)
const icon = (name, cls = '') => {
  const it = ITEM[name]
  return `<span class="icon-frame g-${it ? it.grade : 'Common'} ${cls}">${it ? `<img src="${it.icon}" alt="" loading="lazy">` : ''}</span>`
}
const gradeOf = (name) => (ITEM[name] ? ITEM[name].grade : 'Common')

/* Header */
function renderHeader() {
  const w = world()
  document.body.dataset.side = w.side
  $('#crest-name').textContent = w.name
  $('#crest-side').textContent = w.side
  $('#crest-emblem').dataset.side = w.side
  $('#crest-region').textContent = SHORT[w.region]
  $('#open-world').title = `${w.name}, ${w.side}, ${SHORT[w.region]}. Matched with ${w.matchedWith.name} (${w.matchedWith.side}) since ${w.matchedSince}. Change world`
  $('#gauge-row').innerHTML = PROFS.map((p) => `<span class="gauge" title="${p.key} ${state.mastery[p.key]}"><span class="gl">${p.short}</span><span class="gn">${state.mastery[p.key]}</span><span class="gb"><i style="width:${state.mastery[p.key]}%"></i></span></span>`).join('') +
    `<span class="gauge-tip" role="tooltip">${PROFS.map((p) => `<div><span>${p.key}</span><b>${state.mastery[p.key]}</b></div>`).join('')}<div class="hint">Click to change mastery</div></span>`
  $('#tax-val').textContent = `${state.tax}%`
  $('#scan-world').textContent = w.name
}

