/* Scanner */
const SCAN = [
  ["Artisan's Splendent Orichalcum Helm", 'Tailoring', 30, 10330435, 19999999, 8669564, 83.9],
  ['True Dragon Lord Helm', 'Tailoring', 55, 33568697, 45333333, 7597969, 22.6],
  ["Artisan's Splendent Orichalcum Greaves", 'Tailoring', 35, 10626390, 18999990, 7423601, 69.9],
  ['True Dragon Lord Boots', 'Tailoring', 60, 37289586, 45555555, 5988191, 16.1],
  ["Artisan's Splendent Orichalcum Gloves", 'Tailoring', 35, 9490777, 14980000, 4740223, 49.9],
].map(([name, prof, lvl, craft, market, margin, pct]) => ({ name, prof, lvl, craft, market, margin, pct }))
const scan = { key: 'margin', dir: 'desc', prof: 'All', q: '', showHidden: false }
const fmt = (n) => n.toLocaleString('en-US')
function renderScanner() {
  $('#prof-row').innerHTML = [{ key: 'All', short: '*' }, ...PROFS].map((p) =>
    `<button class="prof" data-prof="${p.key}" aria-pressed="${scan.prof === p.key}"><span class="pe" aria-hidden="true">${p.key === 'All' ? '&#10022;' : p.short}</span><span class="pl">${p.key}</span></button>`).join('')
  let rows = SCAN.filter((r) => (scan.prof === 'All' || r.prof === scan.prof) && r.name.toLowerCase().includes(scan.q.toLowerCase()))
  const k = scan.key, d = scan.dir === 'asc' ? 1 : -1
  rows.sort((a, b) => (k === 'name' ? a.name.localeCompare(b.name) : a[k] - b[k]) * d)
  document.querySelectorAll('#scan-table th').forEach((th) => {
    const key = th.querySelector('button').dataset.sort
    if (key === k) th.setAttribute('aria-sort', scan.dir === 'asc' ? 'ascending' : 'descending'); else th.removeAttribute('aria-sort')
  })
  const sc = (key) => (key === k ? ' sorted' : '')
  $('#scan-table tbody').innerHTML = rows.length ? rows.map((r) => `<tr>
    <td class="first${sc('name')}"><span class="cell-item">${icon(r.name)}<span><span class="name g-${gradeOf(r.name)}">${esc(r.name)}</span><span class="prof-sub">${r.prof} ${r.lvl}</span></span></span></td>
    <td class="num${sc('craft')}" data-label="Craft cost">${fmt(r.craft)}</td>
    <td class="num${sc('market')}" data-label="Market lowest">${fmt(r.market)}</td>
    <td class="num margin${sc('margin')}" data-label="Margin">+${fmt(r.margin)}</td>
    <td class="num${sc('pct')}" data-label="Margin %">+${r.pct.toFixed(1)}%</td></tr>`).join('')
    : `<tr><td colspan="5" class="empty">No ${scan.prof === 'All' ? '' : scan.prof + ' '}recipe matches${scan.q ? ` "${esc(scan.q)}"` : ''} with a price on ${esc(world().name)}. Try another profession, or show the hidden rows.</td></tr>`
  $('#hidden-text').textContent = scan.showHidden
    ? '212 hidden rows are listed under the ranked ones in the full build: 180 wait for a price, 32 need more mastery.'
    : '212 rows hidden: 180 need a price, 32 need more mastery.'
  $('#hidden-toggle').textContent = scan.showHidden ? 'Hide them' : 'Show them'
  $('#hidden-toggle').setAttribute('aria-expanded', scan.showHidden)
}
$('#scan-table thead').addEventListener('click', (e) => {
  const b = e.target.closest('button[data-sort]'); if (!b) return
  const key = b.dataset.sort
  if (scan.key === key) scan.dir = scan.dir === 'asc' ? 'desc' : 'asc'
  else { scan.key = key; scan.dir = key === 'name' ? 'asc' : 'desc' }
  renderScanner()
})
$('#prof-row').addEventListener('click', (e) => { const b = e.target.closest('.prof'); if (b) { scan.prof = b.dataset.prof; renderScanner() } })
$('#name-filter').addEventListener('input', (e) => { scan.q = e.target.value; renderScanner() })
$('#hidden-toggle').addEventListener('click', () => { scan.showHidden = !scan.showHidden; renderScanner() })

/* World picker */
const sideCount = (code, side) => REGIONS.find((r) => r.code === code).worlds.filter((w) => w.side === side).length
const worldRow = (w, withRegion) => {
  const cur = w.id === state.worldId
  const tag = cur ? '<span class="tag cur">Current</span>' : !w.hasData ? '<span class="tag">No prices yet</span>' : ''
  return `<li><button class="wrow${w.hasData ? '' : ' nodata'}" data-world="${w.id}" aria-current="${cur}">
    <span class="wn">${withRegion ? `<span class="res-region" title="${REGIONS.find((r) => r.code === w.region).name}">${w.region}</span>` : ''}${esc(w.name)}${withRegion ? ` <span class="side-badge ${w.side}">${w.side}</span>` : ''}</span>
    <span class="wm">Matched with <span class="${w.matchedWith.side}">${esc(w.matchedWith.name)}</span>, ${w.matchedWith.side}, since ${w.matchedSince}</span>${tag}</button></li>`
}
function renderPicker() {
  const cols = $('#cols')
  if (cols.dataset.step !== picker.step) cols.scrollTop = 0
  cols.dataset.step = picker.step
  const order = ['region', 'side', 'world']
  document.querySelectorAll('#steps li').forEach((li) => {
    const i = order.indexOf(li.dataset.step), now = order.indexOf(picker.step)
    li.className = i < now ? 'done' : i === now ? 'now' : 'todo'
    li.querySelector('button').textContent = i < now ? [SHORT[picker.region], picker.side][i] : ['Region', 'Side', 'World'][i]
    if (i === now) li.setAttribute('aria-current', 'step'); else li.removeAttribute('aria-current')
  })
  $('#region-list').innerHTML = REGIONS.map((r) => `<li><button class="region" data-region="${r.code}" aria-current="${r.code === picker.region}">
    <span class="rn">${r.name}</span><span class="cnt">${r.code}, ${r.worlds.length} worlds</span></button></li>`).join('')
  $('#side-cards').innerHTML = ['Elyos', 'Asmodian'].map((s) => `<button class="side-card" data-side="${s}" aria-current="${s === picker.side}">
    <span class="emblem" data-side="${s}" aria-hidden="true"></span><span class="sn">${s}</span><span class="sc">${sideCount(picker.region, s)} worlds in ${SHORT[picker.region]}</span></button>`).join('')
  $('#world-col-h').textContent = `${picker.side} worlds in ${REGIONS.find((r) => r.code === picker.region).name}`
  $('#wlist').innerHTML = REGIONS.find((r) => r.code === picker.region).worlds.filter((w) => w.side === picker.side).map((w) => worldRow(w)).join('')
  const q = picker.q.trim().toLowerCase()
  cols.classList.toggle('searching', !!q)
  $('.col-results').hidden = !q
  if (q) {
    const hits = WORLDS.filter((w) => w.name.toLowerCase().includes(q))
    $('#results-h').textContent = `${hits.length} world${hits.length === 1 ? '' : 's'} named like "${picker.q.trim()}" across all regions`
    $('#results').innerHTML = hits.length ? hits.map((w) => worldRow(w, true)).join('') : `<li class="empty">No world matches "${esc(picker.q.trim())}". Check the spelling, or pick a region below.</li>`
  }
}
function openWorld(step = 'region') {
  const w = world()
  Object.assign(picker, { region: w.region, side: w.side, step, q: '' })
  $('#world-q').value = ''
  renderPicker()
  if (!$('#world-dlg').open) $('#world-dlg').showModal()
  $('#cols').scrollTop = 0
}
$('#world-dlg').addEventListener('click', (e) => {
  const t = e.target
  const r = t.closest('[data-region]'); if (r) { picker.region = r.dataset.region; picker.step = 'side'; return renderPicker() }
  const s = t.closest('.side-card'); if (s) { picker.side = s.dataset.side; picker.step = 'world'; return renderPicker() }
  const b = t.closest('[data-back]'); if (b) { picker.step = b.dataset.back; return renderPicker() }
  const st = t.closest('#steps li.done'); if (st) { picker.step = st.dataset.step; return renderPicker() }
  const w = t.closest('[data-world]'); if (w) { state.worldId = Number(w.dataset.world); renderAll(); $('#world-dlg').close() }
})
$('#world-q').addEventListener('input', (e) => { picker.q = e.target.value; renderPicker() })

/* Settings */
function renderSettings() {
  $('#mastery-rows').innerHTML = PROFS.map((p) => `<div class="m-row">
    <label class="m-name" for="m-${p.key}">${p.key}${p.game !== p.key ? `<small>${p.game} in game</small>` : '<small>Same name in game</small>'}</label>
    <input type="range" min="0" max="100" value="${state.mastery[p.key]}" data-m="${p.key}" aria-label="${p.key} mastery">
    <span class="num-in"><input id="m-${p.key}" type="number" min="0" max="100" value="${state.mastery[p.key]}" data-m="${p.key}"></span></div>`).join('')
  $('#tax-in').value = state.tax
  $('#tax-label').textContent = `${state.tax}%`
}
$('#mastery-rows').addEventListener('input', (e) => {
  const k = e.target.dataset.m; if (!k) return
  const v = Math.max(0, Math.min(100, Number(e.target.value) || 0))
  state.mastery[k] = v
  e.target.closest('.m-row').querySelectorAll('input').forEach((i) => { if (i !== e.target) i.value = v })
  renderHeader()
})
$('#tax-in').addEventListener('input', (e) => { state.tax = Number(e.target.value) || 0; $('#tax-label').textContent = `${state.tax}%`; renderHeader() })
function openSettings(section) {
  renderSettings()
  if (!$('#settings-dlg').open) $('#settings-dlg').showModal()
  if (section) $(`#set-${section}`).scrollIntoView({ block: 'start' })
}

/* Misc controls */
document.querySelectorAll('.seg').forEach((g) => g.addEventListener('click', (e) => {
  const b = e.target.closest('button'); if (!b) return
  g.querySelectorAll('button').forEach((x) => x.setAttribute('aria-checked', x === b))
}))
document.querySelectorAll('[data-close]').forEach((b) => b.addEventListener('click', () => b.closest('dialog').close()))
document.querySelectorAll('dialog').forEach((d) => d.addEventListener('close', () => {
  if (/^#(world|settings)/.test(location.hash)) history.replaceState(null, '', state.view === 'scanner' ? '#scanner' : '#calc')
}))
$('#open-world').addEventListener('click', () => { location.hash = 'world' })
$('#open-mastery').addEventListener('click', () => { location.hash = 'settings' })
$('#open-tax').addEventListener('click', () => { location.hash = 'settings-tax' })

/* Routes: #calc #scanner #world #world-side #world-list #settings #settings-tax, plus #scanner+world style combos via "&" */
function setView(v) {
  state.view = v
  $('#view-calc').hidden = v !== 'calc'
  $('#view-scanner').hidden = v !== 'scanner'
  document.querySelectorAll('.tab').forEach((t) => (t.dataset.view === v ? t.setAttribute('aria-current', 'page') : t.removeAttribute('aria-current')))
}
function route() {
  const parts = location.hash.slice(1).split('&')
  setView(parts.includes('scanner') ? 'scanner' : parts.some((h) => h === 'calc' || h === '') ? 'calc' : state.view)
  for (const h of parts) {
    if (h === 'world') openWorld('region')
    else if (h === 'world-side') openWorld('side')
    else if (h === 'world-list') openWorld('world')
    else if (h.startsWith('world-q=')) { openWorld('region'); picker.q = decodeURIComponent(h.slice(8)); $('#world-q').value = picker.q; renderPicker() }
    else if (h === 'settings') openSettings()
    else if (h === 'settings-tax') openSettings('tax')
  }
}
function renderAll() { renderHeader(); renderScanner() }
renderCalc(); renderAll(); route()
window.addEventListener('hashchange', route)
